use ratatui::{buffer::Buffer,layout::Rect,style::{Style,Modifier},widgets::{Paragraph,Widget,Wrap}};
use crate::{app::{App,ProcessRow,fuzzy},metrics::Proc};
use super::{SizeClass,kit::*};
pub const SORT_NAMES:[&str;5]=["CPU","MEM","PID","NAME","TIME"];
pub fn draw(b:&mut Buffer,r:Rect,a:&mut App,size:SizeClass){let t=a.theme.clone();let s=a.sample();let detail_w=if size==SizeClass::Wide{38}else{0};let table=Rect::new(r.x,r.y,r.width.saturating_sub(detail_w+if detail_w>0{1}else{0}),r.height);let count=if a.search.as_ref().is_some_and(|q|!q.is_empty()){format!("{} matches / {} processes",a.rows.iter().filter(|r|!r.exited).count(),s.processes.len())}else{format!("{} processes",s.processes.len())};let inner=frame(b,table,"PROCESSES",&count,false,&t);
    let mut y=0;if let Some(query)=&a.search{let search=if a.searching{format!("/ {query}▏")}else{format!("/ {query}    / edit · Esc clear")};line(b,inner,y,search,t.accent);y+=1;}
    let caption=if a.cursor.is_some(){format!("SNAPSHOT −{}  · signals disabled  · sorted {}",duration(a.latest_time()-s.process_at),SORT_NAMES[a.sort])}else{format!("100% = {}  · sorted {} {}  · updated {}s ago",if a.cfg.processes.cpu_mode=="machine"{"whole machine"}else{"one CPU core"},SORT_NAMES[a.sort],if a.reverse{"↑"}else{"↓"},(s.at-s.process_at).max(0.)as u32)};line(b,inner,y,caption,t.muted);y+=2;
    let available=inner.height.saturating_sub(y+1)as usize;let selected=a.rows.iter().position(|r|Some(r.process.key())==a.selected_process).unwrap_or(0);if selected<a.scroll{a.scroll=selected;}if selected>=a.scroll+available.max(1){a.scroll=selected+1-available.max(1);}a.scroll=a.scroll.min(a.rows.len().saturating_sub(available));
    let layout=Columns::new(inner.width);let heading=Rect::new(inner.x,inner.y+y,inner.width,1);for (name,x,w)in layout.headers(){let active=name.trim()==SORT_NAMES[a.sort];text(b,heading,x,0,truncate(name,w as usize),if active{t.accent}else{t.muted});}y+=1;
    let query=a.search.as_deref().unwrap_or("");
    for (i,row0) in a.rows.iter().skip(a.scroll).take(available).enumerate(){let rr=Rect::new(inner.x,inner.y+y+i as u16,inner.width,1);let selected=Some(row0.process.key())==a.selected_process;draw_row(b,rr,row0,&layout,selected,query,a);a.hitmap.add(rr,2,Hit::Process(row0.process.key()));}
    if a.rows.is_empty(){line(b,inner,y+2,if s.processes.is_empty(){"Acquiring process snapshot…"}else{"No matching processes. Esc clears the filter."},t.muted);}
    if a.rows.len()>available&&inner.width>0{let track=available as u16;let thumb=((selected as f32/a.rows.len().max(1)as f32)*track as f32)as u16;for i in 0..track{text(b,inner,inner.width-1,y+i,if i==thumb{"┃"}else{"│"},if i==thumb{t.accent}else{t.wire});}}
    if detail_w>0{let rail=Rect::new(table.right()+1,r.y,detail_w,r.height);let rr=frame(b,rail,"PROCESS INSPECTOR","Enter for tabs",true,&t);if let Some(p)=a.selected_proc(){overview(b,rr,&p,a);}else{line(b,rr,1,"Select a process to inspect",t.muted);}}
}
struct Columns{pid:u16,name:u16,name_w:u16,cpu:u16,bar:u16,mem:u16,user:Option<u16>,time:Option<u16>,io:Option<u16>}
impl Columns{fn new(w:u16)->Self{let extra=if w>=100{45}else if w>=78{24}else{0};let name_w=w.saturating_sub(36+extra).max(10);let name=8;let cpu=name+name_w+1;let bar=cpu+9;let mem=bar+8;let user=(w>=78).then_some(mem+13);let time=(w>=78).then_some(mem+26);let io=(w>=100).then_some(mem+38);Self{pid:0,name,name_w,cpu,bar,mem,user,time,io}}
fn headers(&self)->Vec<(&str,u16,u16)>{let mut v=vec![("PID",self.pid,7),("NAME",self.name,self.name_w),("CPU",self.cpu,8),("LOAD",self.bar,6),("MEM",self.mem,12)];if let Some(x)=self.user{v.push(("USER",x,12));}if let Some(x)=self.time{v.push(("TIME",x,11));}if let Some(x)=self.io{v.push(("READ / WRITE",x,23));}v}}
fn draw_row(b:&mut Buffer,r:Rect,row0:&ProcessRow,c:&Columns,selected:bool,query:&str,a:&App){let t=&a.theme;let p=&row0.process;if selected{b.set_style(r,Style::new().bg(t.substrate));}let color=if row0.exited{t.muted}else if selected{t.bright}else{t.text};text(b,r,c.pid,0,format!("{:>6}",p.pid),if selected{t.accent}else{t.muted});let prefix=if a.tree{format!("{}{}", "  ".repeat(row0.depth.min(12)),if a.collapsed.contains(&p.pid){"▸ "}else if row0.depth>0{"└ "}else{""})}else if row0.exited{"× ".into()}else if row0.new{"+ ".into()}else{String::new()};let label=truncate(&format!("{prefix}{}",p.name),c.name_w as usize);text(b,r,c.name,0,&label,color);
    if !query.is_empty()&&!query.contains(':'){if let Some((_,indices))=fuzzy(query,&label){for i in indices{if let Some(ch)=label.chars().nth(i as usize){let x=c.name+i as u16;if x<r.width{let cell=&mut b[(r.x+x,r.y)];cell.set_char(ch).set_fg(t.accent).set_style(Style::new().add_modifier(Modifier::BOLD|Modifier::UNDERLINED));}}}}}
    let cpu=if a.cfg.processes.cpu_mode=="machine"{p.cpu/a.sample().core_count()as f32}else{p.cpu};text(b,r,c.cpu,0,format!("{:>6.1}%",cpu),color);if c.bar+6<r.width{meter(b,Rect::new(r.x+c.bar,r.y,6,1),p.cpu/100.,t.cpu,t,a.cfg.ui.glyphs=="ascii");}text(b,r,c.mem,0,format!("{:>10}",bytes(p.memory,&a.cfg.units)),color);if let Some(x)=c.user{text(b,r,x,0,truncate(&p.user,11),t.muted);}if let Some(x)=c.time{text(b,r,x,0,duration(p.runtime as f64),t.muted);}if let Some(x)=c.io{text(b,r,x,0,format!("{} / {}",rate(p.read,&a.cfg.units,false),rate(p.write,&a.cfg.units,false)),t.muted);}}
pub fn overview(b:&mut Buffer,r:Rect,p:&Proc,a:&App){let t=&a.theme;line(b,r,1,&p.name,t.accent);line(b,r,3,format!("PID {:>6}   parent {}",p.pid,p.parent),t.text);line(b,r,4,format!("USER {}",p.user),t.muted);line(b,r,5,format!("STATE {}",p.status),t.muted);line(b,r,7,format!("CPU {:>6.1}%    MEM {}",p.cpu,bytes(p.memory,&a.cfg.units)),t.text);if r.height>9{meter(b,row(r,8,1),p.cpu/(a.sample().core_count()*100)as f32,t.cpu,t,a.cfg.ui.glyphs=="ascii");}line(b,r,10,format!("UP {}",duration(p.runtime as f64)),t.muted);line(b,r,12,format!("READ  {}",rate(p.read,&a.cfg.units,false)),t.muted);line(b,r,13,format!("WRITE {}",rate(p.write,&a.cfg.units,false)),t.muted);line(b,r,15,"GPU / NETWORK ATTRIBUTION",t.muted);line(b,r,16,"Not exposed by this collector",t.muted);
    if r.height>19{line(b,r,18,"COMMAND",t.muted);Paragraph::new(if p.command.is_empty(){"Unavailable"}else{&p.command}).style(Style::new().fg(t.text)).wrap(Wrap{trim:false}).render(Rect::new(r.x,r.y+19,r.width,r.height.saturating_sub(22)),b);}if r.height>3{line(b,r,r.height-2,"f follow   X signal   Enter details",t.accent);}}
